#include <bits/stdc++.h>
using namespace std;

const int MAXN = 300;
const int INF = 1e9;

struct Edge {
    int to, rev, flow, capacity;
    Edge(int to, int rev, int flow, int capacity) : to(to), rev(rev), flow(flow), capacity(capacity) {}
};
vector<Edge> graph[MAXN];

void connect(int u, int v, int c, int rc = 0) {
    Edge e1(v, graph[v].size(), 0, c);
    Edge e2(u, graph[u].size(), 0, rc);
    graph[u].push_back(e1);
    graph[v].push_back(e2);
}

int dist[MAXN], ptr[MAXN], s, t;

bool levelGraph() {
    memset(dist, -1, sizeof(dist));
    dist[s] = 0;
    queue<int> q({s});
    while (!q.empty() && dist[t] == -1) {
        int u = q.front(); q.pop();
        for (auto &edge : graph[u]) {
            int v = edge.to;
            if (dist[v] == -1 && edge.flow < edge.capacity) {
                dist[v] = dist[u] + 1;
                q.push(v);
            }
        }
    }
    return dist[t] != -1;
}

int sendFlow(int u, int flow) {
    if (u == t || flow == 0)
        return flow;
    for (int &i = ptr[u]; i < graph[u].size(); i++) {
        auto &e = graph[u][i];
        int v = e.to;
        if (dist[v] != dist[u] + 1)
            continue;
        if (int pushed = sendFlow(v, min(flow, e.capacity - e.flow))) {
            e.flow += pushed;
            graph[v][e.rev].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

int maxFlow() {
    int totalFlow = 0;
    while (levelGraph()) {
        memset(ptr, 0, sizeof(ptr));
        while (int pushed = sendFlow(s, INT_MAX))
            totalFlow += pushed;
    }
    return totalFlow;
}

int dx[] = {-1, 0, 0, 1};
int dy[] = {0, -1, 1, 0};

int n, m;
using Grid = vector<vector<int>>;
using Point = array<int, 2>;
Grid obs, timeMap, distMap;

void computeDistances(int r, int c, Grid &dis, bool check = false) {
    for (int i = 0; i < n; i++)
        fill(dis[i].begin(), dis[i].end(), -1);
    dis[r][c] = 0;
    queue<Point> q;
    q.push({r, c});
    while (!q.empty()) {
        auto p = q.front(); q.pop();
        if (check && dis[p[0]][p[1]] == timeMap[p[0]][p[1]])
            continue;
        Point neighbor;
        for (int i = 0; i < 4; i++) {
            neighbor = {p[0] + dx[i], p[1] + dy[i]};
            if (neighbor[0] < 0 || neighbor[0] >= n || neighbor[1] < 0 || neighbor[1] >= n || dis[neighbor[0]][neighbor[1]] != -1 || obs[neighbor[0]][neighbor[1]])
                continue;
            if (check && timeMap[neighbor[0]][neighbor[1]] > -1 && dis[p[0]][p[1]]]+1 > timeMap[neighbor[0]][neighbor[1]])
                continue;
            dis[neighbor[0]][neighbor[1]] = dis[p[0]][p[1]] + 1;
            q.push(neighbor);
        }
    }
}

vector<string> lab, rea;

int main() {
    cin >> n >> m;
    lab.resize(n);
    rea.resize(n);
    for (auto &x : lab)
        cin >> x;
    for (auto &x : rea)
        cin >> x;
    obs.assign(n, vector<int>(n));
    timeMap.assign(n, vector<int>(n));
    distMap.assign(n, vector<int>(n));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            obs[i][j] = (lab[i][j] == 'Y');
    for (int i = 0; i < n; i++)
        for (int j = 0; j < n; j++)
            if (lab[i][j] == 'Z')
                computeDistances(i, j, timeMap);
    s = 2 * n * n + 5;
    t = s + 1;
    for (int x = 0; x < n; x++) {
        for (int y = 0; y < n; y++) {
            if (lab[x][y] == 'Z' || lab[x][y] == 'Y')
                continue;
            connect(s, n * x + y, lab[x][y] - '0');
            connect(n * n + n * x + y, t, rea[x][y] - '0');
            computeDistances(x, y, distMap, true);
            for (int xp = 0; xp < n; xp++) {
                for (int yp = 0; yp < n; yp++) {
                    if (distMap[xp][yp] != -1 && distMap[xp][yp] <= m) {
                        connect(n * x + y, n * n + n * xp + yp, INF);
                    }
                }
            }
        }
    }
    cout << maxFlow() << '\n';
}
